bad = False
names = set()
for x in M:
    if x["name"] in names:
        print("duplicate mutation name:", x["name"], file=sys.stderr)
        bad = True
    names.add(x["name"])
    text = open(os.path.join(root, x["file"])).read()
    n = text.count(x["find"])
    if n != 1:
        print("find occurs", n, "times:", x["name"], file=sys.stderr)
        bad = True
    if x["find"] == x["replace"]:
        print("no-op mutation:", x["name"], file=sys.stderr)
        bad = True
if bad:
    sys.exit(1)
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "mutations-bashanalysis.json")
json.dump(M, open(out, "w"), indent=1, ensure_ascii=False)
open(out, "a").write("\n")
print(len(M), "mutations")
